// Writes RULES.md from the rule metadata in the registry.
//
// Usage (from the openair-lint folder):
//   dart run tool/generate_rules_doc.dart          write RULES.md
//   dart run tool/generate_rules_doc.dart --check  exit 1 if RULES.md is old

import 'dart:io';

import 'package:openair_lint/openair_lint.dart';

String generateRulesDoc() {
  final b = StringBuffer()
    ..writeln('# openair-lint rules')
    ..writeln()
    ..writeln('<!-- This file is generated by '
        '"dart run tool/generate_rules_doc.dart". Do not edit it by hand. -->')
    ..writeln()
    ..writeln('openair-lint $packageVersion has ${allRules.length} '
        'rule${allRules.length == 1 ? '' : 's'}. Each rule has an ID, a '
        'severity and the versions of the specification that it applies to.')
    ..writeln()
    ..writeln('- **error**: the file breaks a "must" rule of the '
        'specification.')
    ..writeln('- **warning**: the file breaks a "should" rule of the '
        'specification.')
    ..writeln('- **info**: a hint about style or a recommended order.')
    ..writeln()
    ..writeln('Use `openair-lint --explain <rule-id>` to see a rule in the '
        'terminal, and `--disable <rule-id>` to turn a rule off.')
    ..writeln();

  for (final g in ruleGroups) {
    b.writeln('## ${g.title}');
    b.writeln();
    if (g.rules.isEmpty) {
      b.writeln('No rules yet.');
      b.writeln();
      continue;
    }
    b.writeln('| Rule | Severity | Versions | Description |');
    b.writeln('| --- | --- | --- | --- |');
    for (final r in g.rules) {
      b.writeln('| [`${r.id}`](#${r.id}) | ${r.severity.label} | '
          '${r.versionsLabel} | ${_cell(r.description)} |');
    }
    b.writeln();
    for (final r in g.rules) {
      b
        ..writeln('### ${r.id}')
        ..writeln()
        ..writeln('- Severity: **${r.severity.label}**')
        ..writeln('- Versions: ${r.versionsLabel}')
        ..writeln('- Specification: [${r.specAnchor}](${r.specUrl})')
        ..writeln()
        ..writeln(r.description)
        ..writeln()
        ..writeln(r.explanation.trim())
        ..writeln()
        ..writeln('Correct:')
        ..writeln()
        ..writeln('```')
        ..writeln(r.correctExample.trimRight())
        ..writeln('```')
        ..writeln()
        ..writeln('Incorrect:')
        ..writeln()
        ..writeln('```')
        ..writeln(r.incorrectExample.trimRight())
        ..writeln('```')
        ..writeln();
    }
  }
  return b.toString();
}

String _cell(String s) => s.replaceAll('|', r'\|');

void main(List<String> args) {
  final file = File('RULES.md');
  final text = generateRulesDoc();
  if (args.contains('--check')) {
    final old = file.existsSync() ? file.readAsStringSync() : '';
    if (old.replaceAll('\r\n', '\n') != text) {
      stderr.writeln('RULES.md is not up to date. '
          'Run "dart run tool/generate_rules_doc.dart".');
      exitCode = 1;
    } else {
      stdout.writeln('RULES.md is up to date.');
    }
    return;
  }
  file.writeAsStringSync(text);
  stdout.writeln('Wrote RULES.md. Rules: ${allRules.length}.');
}
